problem.brute_solution:
class Solution:
    def findBook(self, bookList: List[List[int]], query: int) -> int:
        n = len(bookList)
        if n == 0:
            return -1
        if query < bookList[0][0] or query > bookList[-1][1]:
            return -1
        ans = -1
        for i in range(n):
            l, r = bookList[i]
            if l <= query <= r:
                ans = i
        return ans

