problem.optimal_solution:
class Solution:
    def findBook(self, bookList: List[List[int]], query: int) -> int:
        n = len(bookList)
        if n == 0:
            return -1
        lo, hi = 0, n - 1
        ans = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            l, r = bookList[mid]
            if query < l:
                hi = mid - 1
            else:
                ans = mid
                if query > r:
                    lo = mid + 1
                else:
                    return mid
        return ans

