class Solution:
    def findBook(self, bookList: List[List[int]], query: int) -> int:
        if not bookList:
            return -1
        n = len(bookList)
        if query < bookList[0][0] or query > bookList[-1][1]:
            return -1
        ans = -1
        for i in range(n):
            if bookList[i][0] > query:
                break
            if query <= bookList[i][1]:
                ans = i
        return ans
